import math

def hitung_bilangan_ganjil(digits):
    n = len(digits)
    n_odd = sum(1 for d in digits if d % 2 == 1)
    if n < 3 or n_odd == 0:
        return 0
    return n_odd * (n - 1) * (n - 2)

def peluang_komite(n_merah, n_putih, ambil, target_merah):
    target_putih = ambil - target_merah
    if target_merah < 0 or target_putih < 0 or target_merah > n_merah or target_putih > n_putih:
        return 0.0
    return (math.comb(n_merah, target_merah) * math.comb(n_putih, target_putih)) / math.comb(n_merah + n_putih, ambil)

