def posterior_bayes(priors, likelihoods):
    if len(priors) != len(likelihoods):
        raise ValueError('Panjang priors dan likelihoods harus sama')
    joints = [p * l for p, l in zip(priors, likelihoods)]
    evidence = sum(joints)
    if evidence <= 0:
        raise ValueError('Total peluang P(B) harus positif')
    return [j / evidence for j in joints]

