import math
import numpy as np

def pdf_order_k_uniform(y, n, k):
    if y <= 0.0 or y >= 1.0:
        return 0.0
    coef = math.factorial(n) / (math.factorial(k - 1) * math.factorial(n - k))
    return coef * (y ** (k - 1)) * ((1.0 - y) ** (n - k))

