import math
from collections import Counter

def permutasi_kata(kata):
    denom = 1
    for cnt in Counter(kata).values():
        denom *= math.factorial(cnt)
    return math.factorial(len(kata)) // denom

def melingkar_berdampingan(n, k_blok):
    if k_blok > n or k_blok < 1:
        return 0
    jumlah_unit = n - k_blok + 1
    return math.factorial(jumlah_unit - 1) * math.factorial(k_blok)

def partisi_multinomial(n, ukuran_kelompok):
    if sum(ukuran_kelompok) != n:
        raise ValueError('Jumlah ukuran kelompok harus sama dengan n')
    denom = 1
    for k in ukuran_kelompok:
        denom *= math.factorial(k)
    return math.factorial(n) // denom

import math

def tim_minimal(n_sd, n_mat, ukuran_tim, min_sd):
    total = 0
    for k in range(min_sd, min(n_sd, ukuran_tim) + 1):
        sisa = ukuran_tim - k
        if 0 <= sisa <= n_mat:
            total += math.comb(n_sd, k) * math.comb(n_mat, sisa)
    return total

def susun_tanpa_berdempetan(n_konsonan_unik, n_vokal_identik):
    celah = n_konsonan_unik + 1
    if n_vokal_identik > celah:
        return 0
    return math.factorial(n_konsonan_unik) * math.comb(celah, n_vokal_identik)

