def distribusi_selisih_dadu():
    counts = {k: 0 for k in range(6)}
    total = 0
    for d1, d2 in itertools.product(range(1, 7), repeat=2):
        counts[abs(d1 - d2)] += 1
        total += 1
    return {k: v / total for k, v in counts.items()}

def melingkar_selang_seling(n):
