import numpy as np

def reliabilitas_analitik(probs):
    p_seri = math.prod(probs)
    p_semua_gagal = math.prod(1.0 - p for p in probs)
    return float(p_seri), float(1.0 - p_semua_gagal)

def simulasi_paralel(probs, n_sim=100_000):
    rng = np.random.default_rng(10)
    u = rng.random((n_sim, len(probs)))
    aktif = u < np.asarray(probs)
    return float(np.mean(np.any(aktif, axis=1)))

