from scipy.integrate import quad

def fpp_segitiga(x):
    if 0.0 <= x < 1.0:
        return float(x)
    if 1.0 <= x <= 2.0:
        return float(2.0 - x)
    return 0.0

def cdf_segitiga(x):
    if x <= 0.0:
        return 0.0
    if x >= 2.0:
        return 1.0
    if x <= 1.0:
        val, _ = quad(fpp_segitiga, 0.0, x)
        return float(val)
    val1, _ = quad(fpp_segitiga, 0.0, 1.0)
    val2, _ = quad(fpp_segitiga, 1.0, x)
    return float(val1 + val2)

