def peluang_genap_geometri(N_trunc=100):
    s_all = sum((1.0 / 3.0) ** x for x in range(1, N_trunc + 1))
    c = 1.0 / s_all
    p_gen = c * sum((1.0 / 3.0) ** x for x in range(2, N_trunc + 1, 2))
    return float(c), float(p_gen)

def peluang_ekor_teleskopik(k):
    eksak = 1.0 / k
    numerik = sum(1.0 / (x * (x + 1)) for x in range(k, 10001))
    return float(eksak), float(numerik)

