import numpy as np
from scipy.integrate import quad

def estimasi_fpp_dari_cdf(F, x, h=1e-6):
    return float((F(x + h) - F(x - h)) / (2.0 * h))

def cek_cdf_valid(F, a, b):
    grid = np.linspace(a + 1e-4, b - 1e-4, 100)
    vals = [estimasi_fpp_dari_cdf(F, float(t)) for t in grid]
    if any(v < -1e-9 for v in vals):
        return False
    area, _ = quad(lambda t: estimasi_fpp_dari_cdf(F, t), a, b, limit=100)
    return bool(abs(area - (F(b) - F(a))) < 1e-4)

import math
import numpy as np

def tabel_joint_bola(n_merah, n_putih, n_biru, ambil):
    P = np.zeros((ambil + 1, ambil + 1), dtype=float)
    total_cara = math.comb(n_merah + n_putih + n_biru, ambil)
    for x in range(ambil + 1):
        for y in range(ambil + 1 - x):
            z = ambil - x - y
            if x <= n_merah and y <= n_putih and z <= n_biru:
                P[x, y] = (math.comb(n_merah, x) * math.comb(n_putih, y) * math.comb(n_biru, z)) / total_cara
    p_y0 = P[:, 0].sum()
    p_x2_given_y0 = float(P[2, 0] / p_y0) if p_y0 > 0 else 0.0
    return P, p_x2_given_y0

