def cek_cauchy_schwarz(var_x, var_y, cov_xy):
    denom = math.sqrt(var_x * var_y)
    rho = cov_xy / denom
    valid = abs(cov_xy) <= denom + 1e-12
    return bool(valid), float(rho)

import numpy as np
from scipy.stats import poisson, binom

def bersyarat_poisson(k, n, lam1, lam2):
    dari_rasio = float((poisson.pmf(k, lam1) * poisson.pmf(n - k, lam2)) / poisson.pmf(n, lam1 + lam2))
    dari_binom = float(binom.pmf(k, n=n, p=lam1 / (lam1 + lam2)))
    return dari_rasio, dari_binom

