import math
from scipy.stats import binom

def mgf_diskrit_dari_pmf(pmf, t):
    return float(sum(math.exp(t * x) * p for x, p in pmf.items()))

def cek_penjumlahan_binomial(t):
    pmf1 = {k: float(binom.pmf(k, 4, 0.3)) for k in range(5)}
    pmf2 = {k: float(binom.pmf(k, 6, 0.3)) for k in range(7)}
    pmf_sum = {k: float(binom.pmf(k, 10, 0.3)) for k in range(11)}
    m_prod = mgf_diskrit_dari_pmf(pmf1, t) * mgf_diskrit_dari_pmf(pmf2, t)
    m_sum = mgf_diskrit_dari_pmf(pmf_sum, t)
    return m_prod, m_sum

import math

def momen_dari_cgf(M, h=1e-4):
    K = lambda t: math.log(M(t))
    k1 = (K(h) - K(-h)) / (2.0 * h)
    k2 = (K(h) - 2.0 * K(0.0) + K(-h)) / (h ** 2)
    return float(k1), float(k2)

import math
import numpy as np
from scipy.integrate import quad

def fpp_y_asimetris(y):
    if 0.0 < y < 1.0:
        return 1.0 / (3.0 * math.sqrt(y))
    if 1.0 <= y < 4.0:
        return 1.0 / (6.0 * math.sqrt(y))
    return 0.0

def verifikasi_asimetris():
    rng = np.random.default_rng(33)
    i1, _ = quad(fpp_y_asimetris, 0.0, 1.0)
    i2, _ = quad(fpp_y_asimetris, 1.0, 4.0)
    x = rng.uniform(-1.0, 2.0, size=100_000)
    y = x ** 2
    return {
        'integral_total': float(i1 + i2),
        'p_lt_1_ana': float(i1),
        'p_lt_1_emp': float(np.mean(y < 1.0)),
    }

